#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int matrixScore(vector<vector<int>>& A) {
        int m = A.size(), n = A[0].size();
        for (int i = 0; i < m; ++i) {
            if (A[i][0] == 0) {
                for (int j = 0; j < n; ++j) A[i][j] ^= 1;
            }
        }

        int score = 0;
        for (int j = 0; j < n; ++j) {
            int count = 0;
            for (int i = 0; i < m; ++i) count += A[i][j];
            score += max(count, m - count) * (1 << (n - j - 1));
        }

        return score;
    }
};
